"use client";

import { useActionState, useState } from "react";
import { Check, LoaderCircle, PenLine } from "lucide-react";
import { saveNotes } from "@/app/actions";

export function NotesEditor({
  id,
  initialNotes,
}: {
  id: string;
  initialNotes: string;
}) {
  const [notes, setNotes] = useState(initialNotes);
  const [state, action, pending] = useActionState(saveNotes, {});
  const dirty = notes !== initialNotes;
  return (
    <section className="notes-section">
      <div className="section-heading">
        <div className="section-title">
          <PenLine size={20} strokeWidth={1.6} />
          <h2>Your notes</h2>
        </div>
        <span className="section-caption">Thoughts worth keeping.</span>
      </div>
      <form action={action}>
        <input type="hidden" name="id" value={id} />
        <label htmlFor="book-notes" className="sr-only">
          Your notes
        </label>
        <textarea
          id="book-notes"
          name="notes"
          value={notes}
          onChange={(event) => setNotes(event.target.value)}
          maxLength={20000}
          rows={9}
          placeholder="What’s staying with you? A favorite passage, a big idea, or just how this book made you feel…"
        />
        <div className="notes-toolbar">
          <span aria-live="polite">
            {state.error ? (
              <span className="error-message" role="alert">
                {state.error}
              </span>
            ) : state.success && !dirty ? (
              <span className="saved-message">
                <Check size={14} /> Notes saved
              </span>
            ) : dirty ? (
              "You have unsaved changes"
            ) : (
              "Your thoughts, in your own words."
            )}
          </span>
          <button className="button button-small" disabled={pending || !dirty}>
            {pending && <LoaderCircle className="spin" size={15} />}
            {pending ? "Saving…" : "Save notes"}
          </button>
        </div>
      </form>
    </section>
  );
}
"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { bookStore } from "@/lib/books";

export type ActionState = {
  error?: string;
  success?: string;
  values?: Record<string, string>;
};

function field(form: FormData, name: string) {
  const value = form.get(name);
  return typeof value === "string" ? value : "";
}

export async function addBook(
  _previous: ActionState,
  form: FormData,
): Promise<ActionState> {
  const title = field(form, "title").trim();
  const author = field(form, "author").trim();
  const notes = field(form, "notes").trim();
  const status = field(form, "status");
  const values = { title, author, notes, status };
  if (!title || !author)
    return { error: "Please enter a title and an author.", values };
  if (title.length > 200 || author.length > 200)
    return {
      error: "Keep the title and author to 200 characters each.",
      values,
    };
  if (notes.length > 20000)
    return { error: "Please keep your notes to 20,000 characters.", values };
  if (status !== "reading" && status !== "finished")
    return { error: "Choose a reading status.", values };
  let id: string;
  try {
    const book = await bookStore.add({ title, author, notes, status });
    id = book.id;
  } catch (error) {
    console.error("Unable to add book:", error);
    return {
      error:
        "We couldn’t save this book. Please try again. Your entries are still here.",
      values,
    };
  }
  revalidatePath("/");
  redirect(`/books/${id}`);
}

export async function saveNotes(
  _previous: ActionState,
  form: FormData,
): Promise<ActionState> {
  const id = field(form, "id");
  const notes = field(form, "notes");
  if (notes.length > 20000)
    return { error: "Please keep your notes to 20,000 characters." };
  try {
    await bookStore.update(id, { notes });
  } catch (error) {
    console.error("Unable to save notes:", error);
    return { error: "We couldn’t save your notes. Please try again." };
  }
  revalidatePath(`/books/${id}`);
  revalidatePath("/");
  return { success: "Notes saved." };
}

export async function changeStatus(
  _previous: ActionState,
  form: FormData,
): Promise<ActionState> {
  const id = field(form, "id");
  const status = field(form, "status");
  if (status !== "reading" && status !== "finished")
    return { error: "Choose a valid reading status." };
  try {
    await bookStore.update(id, { status });
  } catch (error) {
    console.error("Unable to change book status:", error);
    return { error: "We couldn’t update this book. Please try again." };
  }
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
  return {};
}
